/* From Uiverse.io by TISEPSE - Source: https://www.youtube.com/watch?v=B7Z6qERVTvM - Tags: material design, black, button */
.__UIV_SCOPE__ a {
  position: relative;
  display: inline-block;
  padding: 15px 30px;
  border: 2px solid #fefefe;
  text-transform: uppercase;
  color: #fefefe;
  text-decoration: none;
  font-weight: 600;
  font-size: 20px;
}

.__UIV_SCOPE__ a::before {
  content: '';
  position: absolute;
  top: 6px;
  left: -2px;
  width: calc(100% + 4px);
  height: calc(100% - 12px);
  background-color: #212121;
  transition: 0.3s ease-in-out;
  transform: scaleY(1);
}

.__UIV_SCOPE__ a:hover::before {
  transform: scaleY(0);
}

.__UIV_SCOPE__ a::after {
  content: '';
  position: absolute;
  left: 6px;
  top: -2px;
  height: calc(100% + 4px);
  width: calc(100% - 12px);
  background-color: #212121;
  transition: 0.3s ease-in-out;
  transform: scaleX(1);
  transition-delay: 0.5s;
}

.__UIV_SCOPE__ a:hover::after {
  transform: scaleX(0);
}

.__UIV_SCOPE__ a span {
  position: relative;
  z-index: 3;
}

.__UIV_SCOPE__ button {
  background-color: none;
  text-decoration: none;
  background-color: #212121;
  border: none;
}
